<?php
namespace Tests\Unit; use PHPUnit\Framework\TestCase;
final class PublicDataCacheSecurityContractTest extends TestCase { public function test_cache_key_is_versioned():void{$s=file_get_contents(dirname(__DIR__,2).'/src/Services/SharedDataCache.php');foreach(['serverId','$p->id','$cap','$p->updatedAt'] as $v)self::assertStringContainsString($v,$s);} public function test_public_gateway_removes_internal_metadata_and_diagnostics():void{$s=file_get_contents(dirname(__DIR__,2).'/src/Services/DefaultSharedDataGateway.php');self::assertStringContainsString('null,null,$r->errorCode,null',$s);self::assertStringNotContainsString('configuration]', $s);} public function test_no_public_http_api_was_added():void{$s=file_get_contents(dirname(__DIR__,2).'/routes/api.php');self::assertStringNotContainsString('SharedDataGateway',$s);} }
